<?php
defined('ABSPATH')||exit;
function morgenbrot_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('automatic-feed-links');add_theme_support('responsive-embeds');add_theme_support('wp-block-styles');add_theme_support('html5',['search-form','comment-form','comment-list','gallery','caption','style','script']);add_theme_support('custom-logo',['height'=>80,'width'=>260,'flex-height'=>true,'flex-width'=>true]);register_nav_menus(['primary'=>'Hauptmenü','footer'=>'Footer-Navigation']);load_theme_textdomain('morgenbrot',get_template_directory().'/languages');}add_action('after_setup_theme','morgenbrot_setup');
function morgenbrot_asset_version($relative){$file=get_template_directory().$relative;return file_exists($file)?(string)filemtime($file):wp_get_theme()->get('Version');}
function morgenbrot_assets(){wp_enqueue_style('morgenbrot-style',get_stylesheet_uri(),[],morgenbrot_asset_version('/style.css'));foreach(['/assets/css/main.css'=>'morgenbrot-main','/assets/css/responsive.css'=>'morgenbrot-responsive']as$file=>$handle)if(file_exists(get_template_directory().$file))wp_enqueue_style($handle,get_template_directory_uri().$file,[$handle==='morgenbrot-main'?'morgenbrot-style':'morgenbrot-main'],morgenbrot_asset_version($file));foreach(['/assets/js/navigation.js'=>'morgenbrot-navigation','/assets/js/product-filters.js'=>'morgenbrot-filters','/assets/js/preorder.js'=>'morgenbrot-preorder','/assets/js/gallery.js'=>'morgenbrot-gallery']as$file=>$handle)if(file_exists(get_template_directory().$file))wp_enqueue_script($handle,get_template_directory_uri().$file,[],morgenbrot_asset_version($file),true);if((is_post_type_archive('bakery_location')||is_singular('bakery_location'))&&file_exists(get_template_directory().'/assets/vendor/leaflet/leaflet.js')){wp_enqueue_style('leaflet',get_template_directory_uri().'/assets/vendor/leaflet/leaflet.css',[],morgenbrot_asset_version('/assets/vendor/leaflet/leaflet.css'));wp_enqueue_script('leaflet',get_template_directory_uri().'/assets/vendor/leaflet/leaflet.js',[],morgenbrot_asset_version('/assets/vendor/leaflet/leaflet.js'),true);wp_enqueue_script('morgenbrot-map',get_template_directory_uri().'/assets/js/locations-map.js',['leaflet'],morgenbrot_asset_version('/assets/js/locations-map.js'),true);$ids=is_singular('bakery_location')?[get_queried_object_id()]:[];wp_localize_script('morgenbrot-map','morgenbrotMapData',['locations'=>function_exists('morgenbrot_get_map_locations')?morgenbrot_get_map_locations($ids):[],'tiles'=>'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png','attribution'=>'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors']);}}add_action('wp_enqueue_scripts','morgenbrot_assets');
function morgenbrot_fallback_menu(){echo'<ul class="nav-menu"><li><a href="'.esc_url(home_url('/')).'">Startseite</a></li><li><a href="'.esc_url(get_post_type_archive_link('bakery_product')?:home_url('/sortiment/')).'">Sortiment</a></li><li><a href="'.esc_url(get_post_type_archive_link('bakery_location')?:home_url('/filialen/')).'">Filialen</a></li><li><a href="'.esc_url(home_url('/ueber-uns/')).'">Über uns</a></li></ul>';}
function morgenbrot_placeholder($kind='bread'){$files=array('bread'=>'morgenbrot-products.webp','basket'=>'morgenbrot-products.webp','wheat'=>'morgenbrot-news.webp','shop'=>'morgenbrot-location.webp','news'=>'morgenbrot-news.webp');$alts=array('bread'=>'Frische handwerkliche Brote und Brötchen','basket'=>'Auswahl frischer Backwaren','wheat'=>'Brot, Äpfel und Getreide in der Backstube','shop'=>'Fiktive Morgenbrot-Filiale','news'=>'Saisonale Neuigkeiten aus der Backstube');$file=$files[$kind]??$files['bread'];echo'<img class="fallback-image fallback-'.esc_attr($kind).'" src="'.esc_url(get_template_directory_uri().'/assets/images/'.$file).'" alt="'.esc_attr($alts[$kind]??$alts['bread']).'" loading="lazy" decoding="async">';}
if(!function_exists('morgenbrot_meta')){function morgenbrot_meta($id,$key){return get_post_meta($id,'_morgenbrot_'.$key,true);}}
function morgenbrot_breadcrumbs(){if(is_front_page())return;echo'<nav class="breadcrumbs shell" aria-label="Brotkrumen"><ol><li><a href="'.esc_url(home_url('/')).'">Startseite</a></li>';if(is_singular('bakery_product'))echo'<li><a href="'.esc_url(get_post_type_archive_link('bakery_product')).'">Sortiment</a></li>';elseif(is_singular('bakery_location'))echo'<li><a href="'.esc_url(get_post_type_archive_link('bakery_location')).'">Filialen</a></li>';if(is_singular())echo'<li aria-current="page">'.esc_html(get_the_title()).'</li>';elseif(is_post_type_archive('bakery_product'))echo'<li aria-current="page">Sortiment</li>';elseif(is_post_type_archive('bakery_location'))echo'<li aria-current="page">Filialen</li>';elseif(is_home())echo'<li aria-current="page">Aktuelles</li>';elseif(is_search())echo'<li aria-current="page">Suche</li>';elseif(is_404())echo'<li aria-current="page">404</li>';echo'</ol></nav>';}
function morgenbrot_enhancement_assets(){wp_enqueue_style('morgenbrot-enhancements',get_template_directory_uri().'/assets/css/enhancements.css',array('morgenbrot-main'),morgenbrot_asset_version('/assets/css/enhancements.css'));}add_action('wp_enqueue_scripts','morgenbrot_enhancement_assets',20);
function morgenbrot_page_url($demo_key,$fallback){$posts=get_posts(array('post_type'=>'page','post_status'=>'publish','numberposts'=>1,'meta_key'=>'_morgenbrot_demo_key','meta_value'=>'page_'.$demo_key));return$posts?get_permalink($posts[0]):home_url('/'.$fallback.'/');}
function morgenbrot_fix_assets(){wp_enqueue_style('morgenbrot-fixes',get_template_directory_uri().'/assets/css/fixes.css',array('morgenbrot-enhancements'),morgenbrot_asset_version('/assets/css/fixes.css'));wp_enqueue_style('morgenbrot-pages',get_template_directory_uri().'/assets/css/pages.css',array('morgenbrot-fixes'),morgenbrot_asset_version('/assets/css/pages.css'));}add_action('wp_enqueue_scripts','morgenbrot_fix_assets',30);
function morgenbrot_front_map_assets(){if(!is_front_page())return;wp_enqueue_style('leaflet',get_template_directory_uri().'/assets/vendor/leaflet/leaflet.css',array(),morgenbrot_asset_version('/assets/vendor/leaflet/leaflet.css'));wp_enqueue_script('leaflet',get_template_directory_uri().'/assets/vendor/leaflet/leaflet.js',array(),morgenbrot_asset_version('/assets/vendor/leaflet/leaflet.js'),true);wp_enqueue_script('morgenbrot-map',get_template_directory_uri().'/assets/js/locations-map.js',array('leaflet'),morgenbrot_asset_version('/assets/js/locations-map.js'),true);wp_localize_script('morgenbrot-map','morgenbrotMapData',array('locations'=>function_exists('morgenbrot_get_map_locations')?morgenbrot_get_map_locations():array(),'tiles'=>'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png','attribution'=>'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'));}add_action('wp_enqueue_scripts','morgenbrot_front_map_assets',15);

/* Aktuelles is intentionally disabled on the public site; posts remain safely in admin. */
function morgenbrot_hide_aktuelles_menu_item( $items ) {
	return array_values( array_filter( $items, function( $item ) {
		$url = untrailingslashit( (string) $item->url );
		return ! ( str_ends_with( $url, '/aktuelles' ) || ( 'page' === $item->object && absint( $item->object_id ) === absint( get_option( 'page_for_posts' ) ) ) );
	} ) );
}
add_filter( 'wp_nav_menu_objects', 'morgenbrot_hide_aktuelles_menu_item' );
function morgenbrot_disable_public_news() {
	if ( is_admin() || wp_doing_ajax() ) return;
	if ( is_home() || is_singular( 'post' ) || is_category() || is_tag() || is_author() || is_date() ) {
		wp_safe_redirect( home_url( '/' ), 301 );
		exit;
	}
}
add_action( 'template_redirect', 'morgenbrot_disable_public_news' );
function morgenbrot_exclude_posts_from_search( $query ) {
	if ( ! is_admin() && $query->is_main_query() && $query->is_search() ) $query->set( 'post_type', array( 'page', 'bakery_product', 'bakery_location', 'bakery_promotion' ) );
}
add_action( 'pre_get_posts', 'morgenbrot_exclude_posts_from_search' );
